-- T05 private package and minimal financial source records. No funding/delivery bypass.
grant create on schema api,app_private,finance_private to git_tutor_commands;
create table app_private.learner_financial_mutex(learner_id uuid primary key references app_private.learners(id));
create table app_private.package_grant_policy_versions(id uuid primary key default gen_random_uuid(),content jsonb not null,status text not null default 'draft' check(status in('draft','approved','retired')),environment_scope text not null,is_synthetic boolean not null,created_by uuid not null references app_private.accounts(id),approved_by uuid references app_private.accounts(id),approved_at timestamptz,effective_at timestamptz,approval_note text,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app_private.package_purchases(id uuid primary key default gen_random_uuid(),learner_id uuid not null references app_private.learners(id),purchaser_account_id uuid not null references app_private.accounts(id),contract_version_id uuid not null references app_private.policy_versions(id),contract_snapshot jsonb not null,contract_hash text not null,accepted_by uuid not null references app_private.accounts(id),accepted_at timestamptz not null default now(),planned_credit_quanta bigint not null check(planned_credit_quanta between 1 and 9007199254740991),purchase_value_minor bigint not null check(purchase_value_minor between 0 and 9007199254740991),currency text not null check(currency='EGP'),purchase_activation_rule text not null check(purchase_activation_rule='full_settled_charge'),purchase_state text not null default 'pending_funding' check(purchase_state in('pending_funding','activated','cancelled')),activated_at timestamptz,charge_id uuid,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table finance_private.charges(id uuid primary key default gen_random_uuid(),charge_type text not null check(charge_type in('package_purchase','enrollment')),learner_id uuid not null references app_private.learners(id),responsible_account_id uuid not null references app_private.accounts(id),package_purchase_id uuid unique references app_private.package_purchases(id),enrollment_id uuid unique references app_private.enrollments(id),accepted_contract_version_id uuid not null references app_private.policy_versions(id),accepted_terms_hash text not null,amount_minor bigint not null check(amount_minor between 0 and 9007199254740991),currency text not null check(currency='EGP'),state text not null default 'issued' check(state in('draft','issued','voided')),version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((charge_type='package_purchase' and package_purchase_id is not null and enrollment_id is null) or(charge_type='enrollment' and enrollment_id is not null and package_purchase_id is null)));
alter table app_private.package_purchases add foreign key(charge_id) references finance_private.charges(id);
create table finance_private.ledger_transactions(id uuid primary key default gen_random_uuid(),source_posting_key text not null unique,source_type text not null,source_id uuid not null,request_hash text not null,actor_account_id uuid references app_private.accounts(id),command_id uuid not null,currency text not null check(currency='EGP'),effective_at timestamptz not null,recorded_at timestamptz not null default now());
create table finance_private.ledger_lines(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references finance_private.ledger_transactions(id),account_code text not null check(account_code in('receivable','deferred_package_obligation','promotional_subsidy_expense','tuition_revenue')),learner_id uuid references app_private.learners(id),package_purchase_id uuid references app_private.package_purchases(id),lot_id uuid,signed_minor bigint not null check(signed_minor between -9007199254740991 and 9007199254740991),currency text not null check(currency='EGP'),recorded_at timestamptz not null default now());
create table app_private.package_purchase_acceptances(id uuid primary key default gen_random_uuid(),purchase_id uuid not null unique references app_private.package_purchases(id),learner_id uuid not null references app_private.learners(id),actor_account_id uuid not null references app_private.accounts(id),contract_hash text not null,accepted_at timestamptz not null default now());
create table app_private.package_lots(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references app_private.package_purchases(id),learner_id uuid not null references app_private.learners(id),origin_kind text not null check(origin_kind in('purchase','complimentary','approved_credit','transfer')),original_lot_id uuid not null references app_private.package_lots(id) deferrable initially deferred,source_lot_id uuid references app_private.package_lots(id),grant_policy_version_id uuid references app_private.package_grant_policy_versions(id),contract_version_id uuid not null references app_private.policy_versions(id),eligibility_snapshot jsonb not null,base_duration_minutes integer not null check(base_duration_minutes>0),coverage_rule text not null check(coverage_rule in('named_entitlement_covers_eligible_occurrence','allocated_value_with_explicit_top_up')),expires_at timestamptz,grant_source_id uuid not null,balances jsonb not null,version integer not null default 1,created_at timestamptz not null default now());
alter table finance_private.ledger_lines add foreign key(lot_id) references app_private.package_lots(id);
create table app_private.package_reservations(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references app_private.package_purchases(id),learner_id uuid not null references app_private.learners(id),enrollment_id uuid not null references app_private.enrollments(id),quote_id uuid not null references app_private.quotes(id),quote_hash text not null,coverage_rule text not null,required_credit_quanta bigint not null,reserved_credit_quanta bigint not null,allocated_value_minor bigint not null,agreed_top_up_minor bigint,coverage_proposal_id uuid,acceptance_refs jsonb not null default '{}',state text not null default 'reserved' check(state in('reserved','partially_consumed','consumed','released')),expires_at timestamptz not null,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index package_reservation_active on app_private.package_reservations(enrollment_id) where state in('reserved','partially_consumed');
create table app_private.package_reservation_allocations(id uuid primary key default gen_random_uuid(),reservation_id uuid not null references app_private.package_reservations(id),lot_id uuid not null references app_private.package_lots(id),credit_quanta bigint not null check(credit_quanta>0),value_minor bigint not null check(value_minor>=0),created_at timestamptz not null default now());
create table app_private.package_transfers(id uuid primary key default gen_random_uuid(),source_purchase_id uuid not null references app_private.package_purchases(id),target_purchase_id uuid not null references app_private.package_purchases(id),source_lot_id uuid not null references app_private.package_lots(id),target_lot_id uuid not null references app_private.package_lots(id),source_credit_quanta bigint not null check(source_credit_quanta>0),target_credit_quanta bigint not null check(target_credit_quanta>0),value_minor bigint not null check(value_minor>=0),currency text not null check(currency='EGP'),conversion_proposal_id uuid,command_id uuid not null,created_at timestamptz not null default now(),check(source_purchase_id<>target_purchase_id));
create table app_private.entitlement_movements(id uuid primary key default gen_random_uuid(),lot_id uuid not null references app_private.package_lots(id),purchase_id uuid not null references app_private.package_purchases(id),learner_id uuid not null references app_private.learners(id),kind text not null check(kind in('grant','reserve','release','consume','restore','transfer_out','transfer_in','expire','adjust')),enrollment_id uuid references app_private.enrollments(id),reservation_id uuid references app_private.package_reservations(id),allocation_id uuid references app_private.package_reservation_allocations(id),original_movement_id uuid references app_private.entitlement_movements(id),transfer_id uuid references app_private.package_transfers(id) deferrable initially deferred,command_id uuid not null,line_key text not null,policy_version_id uuid not null references app_private.policy_versions(id),delta jsonb not null,credit_quanta bigint not null,value_minor bigint not null,from_bucket text,to_bucket text,customer_reason_code text not null,effective_at timestamptz not null,recorded_at timestamptz not null default now(),unique(command_id,line_key));
create table finance_private.remedy_sources(id uuid primary key default gen_random_uuid(),consumption_id uuid unique references app_private.entitlement_movements(id),learner_id uuid not null references app_private.learners(id),eligible_credit_quanta bigint not null check(eligible_credit_quanta>=0),eligible_value_minor bigint not null check(eligible_value_minor>=0),version integer not null default 1,created_at timestamptz not null default now());
create table app_private.remedy_reservations(id uuid primary key default gen_random_uuid(),source_id uuid not null references finance_private.remedy_sources(id),remedy_id uuid not null,credit_quanta bigint not null check(credit_quanta>=0),value_minor bigint not null check(value_minor>=0),mode text not null check(mode in('restoration','cash','account_credit')),state text not null check(state in('reserved','consumed','released')),command_id uuid not null,created_at timestamptz not null default now(),unique(source_id,remedy_id));
create table app_private.package_due_runs(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references app_private.package_purchases(id),idempotency_key text not null,result jsonb not null,created_at timestamptz not null default now(),unique(purchase_id,idempotency_key));
create index package_purchase_learner on app_private.package_purchases(learner_id,created_at desc,id desc);
create index package_lot_allocation on app_private.package_lots(purchase_id,expires_at,created_at,id);
create index package_movement_source on app_private.entitlement_movements(lot_id,recorded_at,id);

create function app_private.package_empty_balance() returns jsonb language sql immutable set search_path='' as $$
select jsonb_object_agg(bucket||suffix,0) from unnest(array['granted','transferred_in','adjustment','available','reserved','consumed','expired','transferred_out']) bucket cross join unnest(array['_credit_quanta','_value_minor']) suffix
$$;
create function app_private.package_lock_learner(p_learner_id uuid) returns void language plpgsql security definer set search_path='' as $$
begin insert into app_private.learner_financial_mutex(learner_id) values(p_learner_id) on conflict do nothing;perform 1 from app_private.learner_financial_mutex where learner_id=p_learner_id for update;end $$;
create function app_private.package_lock_purchase(p_purchase_id uuid) returns app_private.package_purchases language plpgsql security definer set search_path='' as $$
declare row app_private.package_purchases%rowtype;begin select * into row from app_private.package_purchases where id=p_purchase_id;if row.id is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;perform app_private.package_lock_learner(row.learner_id);select * into row from app_private.package_purchases where id=p_purchase_id for update;return row;end $$;
create function app_private.package_assert_scope(p_actor uuid,p_learner_id uuid,p_scope text,p_allow_admin boolean default false) returns void language plpgsql security definer set search_path='' as $$
begin if p_scope not in('booking','payments') then raise exception 'VALIDATION_ERROR';end if;perform app_private.assert_learner_scope(p_actor,p_learner_id,p_scope,p_allow_admin);end $$;
create function app_private.package_begin(p_actor uuid,p_name text,p_input jsonb,p_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.booking_begin(p_actor,p_name,p_input,p_key) $$;
create function app_private.package_finish(p_context jsonb,p_resource uuid,p_version integer,p_result jsonb,p_event_type text,p_event_payload jsonb) returns jsonb language sql security definer set search_path='' as $$ select app_private.booking_finish(p_context,p_resource,p_version,p_result,p_event_type,p_event_payload) $$;
create function app_private.package_safe_integer(p_value jsonb,p_min numeric default 0) returns bigint language plpgsql immutable set search_path='' as $$
declare n numeric;begin if jsonb_typeof(p_value) is distinct from 'number' then raise exception 'VALIDATION_ERROR';end if;n:=p_value::text::numeric;if n<>trunc(n) or n<p_min or n>9007199254740991 then raise exception 'VALIDATION_ERROR';end if;return n::bigint;end $$;
create function app_private.package_append_movement(p_lot_id uuid,p_kind text,p_delta jsonb,p_refs jsonb,p_context jsonb,p_line_key text) returns uuid language plpgsql security definer set search_path='' as $$
declare lot app_private.package_lots%rowtype;previous app_private.entitlement_movements%rowtype;balances jsonb;key text;amount numeric;suffix text;left_total numeric;right_total numeric;id uuid:=gen_random_uuid();begin
 select * into lot from app_private.package_lots where package_lots.id=p_lot_id for update;if lot.id is null then raise exception 'NOT_FOUND';end if;
 if jsonb_typeof(p_delta) is distinct from 'object' or p_delta='{}' or(p_delta-(select array_agg(k) from jsonb_object_keys(app_private.package_empty_balance()) k))<>'{}' or jsonb_typeof(p_refs) is distinct from 'object' or(p_refs-array['enrollment_id','reservation_id','allocation_id','original_movement_id','transfer_id','credit_quanta','value_minor','from_bucket','to_bucket','customer_reason_code','effective_at'])<>'{}' then raise exception 'VALIDATION_ERROR';end if;
 select * into previous from app_private.entitlement_movements where command_id=(p_context->>'command_id')::uuid and line_key=p_line_key;
 if previous.id is not null then if previous.lot_id<>p_lot_id or previous.kind<>p_kind or previous.delta<>p_delta then raise exception 'IDEMPOTENCY_CONFLICT';end if;return previous.id;end if;
 balances:=lot.balances;
 for key in select jsonb_object_keys(p_delta) loop
  amount:=app_private.package_safe_integer(p_delta->key,-9007199254740991)+(balances->>key)::numeric;
  if abs(amount)>9007199254740991 or(key not like 'adjustment_%' and amount<0) then raise exception 'INSUFFICIENT_ENTITLEMENT';end if;
  balances:=jsonb_set(balances,array[key],to_jsonb(amount));
 end loop;
 foreach suffix in array array['_credit_quanta','_value_minor'] loop
  left_total:=(balances->>('granted'||suffix))::numeric+(balances->>('transferred_in'||suffix))::numeric+(balances->>('adjustment'||suffix))::numeric;
  right_total:=(balances->>('available'||suffix))::numeric+(balances->>('reserved'||suffix))::numeric+(balances->>('consumed'||suffix))::numeric+(balances->>('expired'||suffix))::numeric+(balances->>('transferred_out'||suffix))::numeric;
  if left_total<>right_total then raise exception 'CONSERVATION_VIOLATION';end if;
 end loop;
 foreach key in array array['available','reserved','consumed','expired','transferred_out'] loop if(balances->>(key||'_credit_quanta'))::numeric=0 and(balances->>(key||'_value_minor'))::numeric<>0 then raise exception 'CONSERVATION_VIOLATION';end if;end loop;
 insert into app_private.entitlement_movements(id,lot_id,purchase_id,learner_id,kind,enrollment_id,reservation_id,allocation_id,original_movement_id,transfer_id,command_id,line_key,policy_version_id,delta,credit_quanta,value_minor,from_bucket,to_bucket,customer_reason_code,effective_at)
 values(id,lot.id,lot.purchase_id,lot.learner_id,p_kind,(p_refs->>'enrollment_id')::uuid,(p_refs->>'reservation_id')::uuid,(p_refs->>'allocation_id')::uuid,(p_refs->>'original_movement_id')::uuid,(p_refs->>'transfer_id')::uuid,(p_context->>'command_id')::uuid,p_line_key,lot.contract_version_id,p_delta,app_private.package_safe_integer(p_refs->'credit_quanta',case when p_kind='adjust' then -9007199254740991 else 0 end),app_private.package_safe_integer(p_refs->'value_minor',case when p_kind='adjust' then -9007199254740991 else 0 end),p_refs->>'from_bucket',p_refs->>'to_bucket',coalesce(p_refs->>'customer_reason_code',p_kind),coalesce((p_refs->>'effective_at')::timestamptz,now()));
 update app_private.package_lots set balances=package_append_movement.balances,version=version+1 where package_lots.id=lot.id;return id;
end $$;

create function app_private.package_contract_snapshot(p_contract_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare policy app_private.policy_versions%rowtype;pack jsonb;begin
 select * into policy from app_private.policy_versions where id=p_contract_id;
 pack:=policy.content->'package_contract';
 if policy.id is null or policy.status<>'published' or policy.effective_at>now() or policy.content->>'package_enabled'<>'true' or pack->>'purchase_activation_rule' is distinct from 'full_settled_charge' or pack->>'expiry_clock' is distinct from 'elapsed_24_hour_days' or not exists(select 1 from app_private.offers o where o.policy_version_id=p_contract_id and app_private.booking_offer_sellable(o.id) and pack->'eligible_offer_ids'?o.id::text) then raise exception 'POLICY_INCOMPLETE';end if;
 perform app_private.assert_catalog_publication(app_private.catalog_environment(),policy.environment_scope,policy.is_synthetic);return pack;
end $$;
create function app_private.package_offer_labels(p_contract jsonb) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('offer_id',x.id,'title',case when o.published_at is not null then s.title else 'Unavailable offer' end,'format',coalesce(o.format,'group'),'duration_minutes',coalesce(o.duration_minutes,(p_contract->>'base_duration_minutes')::int),'availability',case when app_private.booking_offer_sellable(x.id) then 'currently_published' when o.published_at is not null then 'historical' else 'unavailable' end) order by x.id),'[]') from(select value::uuid id from jsonb_array_elements_text(p_contract->'eligible_offer_ids'))x left join app_private.offers o on o.id=x.id left join app_private.subjects s on s.id=o.subject_id
$$;
create function app_private.package_contract_dto(p_contract_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare pack jsonb;title text;begin pack:=app_private.package_contract_snapshot(p_contract_id);
 select s.title||' package' into title from app_private.offers o join app_private.subjects s on s.id=o.subject_id where o.policy_version_id=p_contract_id and o.published_at is not null order by o.created_at,o.id limit 1;
 return jsonb_build_object('contract_version_id',p_contract_id,'title',coalesce(title,'Learning package'),'contract',pack,'terms_hash',app_private.catalog_hash(jsonb_build_object('contract_version_id',p_contract_id,'contract',pack)),'purchase_activation_rule',pack->>'purchase_activation_rule','environment_label',case when app_private.catalog_environment() in('test','development') then 'synthetic_development' else 'live' end,'eligible_offers',app_private.package_offer_labels(pack));end $$;
create function app_private.package_balance(p_purchase_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb:=app_private.package_empty_balance();key text;total numeric;begin
 for key in select jsonb_object_keys(result) loop select coalesce(sum((balances->>key)::numeric),0) into total from app_private.package_lots where purchase_id=p_purchase_id;if abs(total)>9007199254740991 then raise exception 'VALUE_OUT_OF_RANGE';end if;result:=jsonb_set(result,array[key],to_jsonb(total));end loop;return result;
end $$;
create function app_private.package_visible_balance(p_balances jsonb) returns jsonb language sql immutable set search_path='' as $$ select p_balances-array['granted_credit_quanta','granted_value_minor','transferred_in_credit_quanta','transferred_in_value_minor','adjustment_credit_quanta','adjustment_value_minor'] $$;
create function app_private.package_pending_proposals(p_purchase_id uuid,p_actor uuid) returns jsonb language sql stable security definer set search_path='' as $$ select '[]'::jsonb $$;
create function app_private.package_summary(p_id uuid,p_actor uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare p app_private.package_purchases%rowtype;c finance_private.charges%rowtype;name text;origins jsonb;title text;begin
 select * into p from app_private.package_purchases where id=p_id;select * into c from finance_private.charges where id=p.charge_id;select display_name into name from app_private.people where id=(select person_id from app_private.learners where id=p.learner_id);
 select s.title||' package' into title from app_private.offers o join app_private.subjects s on s.id=o.subject_id where o.policy_version_id=p.contract_version_id and o.published_at is not null order by o.created_at,o.id limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('origin_kind',origin_kind,'granted_credit_quanta',q,'granted_value_minor',v) order by origin_kind),'[]') into origins from(select origin_kind,sum((balances->>'granted_credit_quanta')::numeric+(balances->>'transferred_in_credit_quanta')::numeric) q,sum((balances->>'granted_value_minor')::numeric+(balances->>'transferred_in_value_minor')::numeric) v from app_private.package_lots where purchase_id=p.id group by origin_kind)x;
 return jsonb_build_object('package_purchase_id',p.id,'version',p.version,'learner',jsonb_build_object('learner_id',p.learner_id,'display_name',name),'contract_version_id',p.contract_version_id,'title',coalesce(title,'Learning package'),'purchase_state',p.purchase_state,'currency',p.currency,'purchased_credit_quanta',p.planned_credit_quanta,'purchase_value_minor',p.purchase_value_minor,'purchased_granted_credit_quanta',coalesce((select sum((balances->>'granted_credit_quanta')::numeric) from app_private.package_lots where purchase_id=p.id and origin_kind='purchase'),0),'charge',jsonb_build_object('charge_id',c.id,'state',c.state,'original_minor',c.amount_minor,'net_minor',c.amount_minor,'allocated_minor',null,'balance_minor',null,'funding_integration_state','awaiting_T06_integration'),'balances',app_private.package_visible_balance(app_private.package_balance(p.id)),'origin_totals',origins,'next_expiry_at',(select min(expires_at) from app_private.package_lots where purchase_id=p.id and (balances->>'available_credit_quanta')::numeric>0),'created_at',p.created_at,'pending_proposals',app_private.package_pending_proposals(p.id,p_actor));
end $$;
create function app_private.package_grant_policy_errors(p_content jsonb) returns text[] language plpgsql immutable set search_path='' as $$
declare value jsonb;begin
 if jsonb_typeof(p_content) is distinct from 'object' or(p_content-array['name','eligible_package_contract_version_ids','currency','valuation_rule','maximum_credit_quanta_per_grant','maximum_carrying_value_minor_per_grant'])<>'{}' then return array['content'];end if;
 if length(btrim(coalesce(p_content->>'name',''))) not between 1 and 200 or p_content->>'currency' is distinct from 'EGP' or p_content->>'valuation_rule' is null or p_content->>'valuation_rule' not in('zero_value','reviewed_exact_capped_subsidy') or jsonb_typeof(p_content->'eligible_package_contract_version_ids') is distinct from 'array' or jsonb_array_length(p_content->'eligible_package_contract_version_ids') not between 1 and 100 then return array['content'];end if;
 for value in select value from jsonb_array_elements(p_content->'eligible_package_contract_version_ids') loop if jsonb_typeof(value)<>'string' then return array['eligible_package_contract_version_ids'];end if;perform(value#>>'{}')::uuid;end loop;
 perform app_private.package_safe_integer(p_content->'maximum_credit_quanta_per_grant',1);perform app_private.package_safe_integer(p_content->'maximum_carrying_value_minor_per_grant');
 if p_content->>'valuation_rule'='zero_value' and(p_content->>'maximum_carrying_value_minor_per_grant')::numeric<>0 then return array['maximum_carrying_value_minor_per_grant'];end if;return '{}';
exception when others then return array['content'];end $$;
create function finance_private.finance_assert_balanced() returns trigger language plpgsql security definer set search_path='' as $$
declare target uuid;begin target:=case when tg_table_name='ledger_transactions' then new.id else new.transaction_id end;
 if exists(select 1 from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.id=target and l.currency<>t.currency) or coalesce((select sum(signed_minor::numeric) from finance_private.ledger_lines where transaction_id=target),0)<>0 then raise exception 'UNBALANCED_JOURNAL';end if;return null;end $$;
create constraint trigger balanced_transaction after insert on finance_private.ledger_transactions deferrable initially deferred for each row execute function finance_private.finance_assert_balanced();
create constraint trigger balanced_lines after insert on finance_private.ledger_lines deferrable initially deferred for each row execute function finance_private.finance_assert_balanced();
create function finance_private.finance_post_balanced(p_source_posting_key text,p_source_type text,p_source_id uuid,p_currency text,p_effective_at timestamptz,p_lines jsonb,p_context jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare id uuid:=gen_random_uuid();saved finance_private.ledger_transactions%rowtype;digest text;line jsonb;total numeric:=0;n bigint;begin
 if p_currency is distinct from 'EGP' or p_source_posting_key is null or length(p_source_posting_key)>200 or p_effective_at is null or not isfinite(p_effective_at) or jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines)>100 then raise exception 'VALIDATION_ERROR';end if;
 digest:=app_private.catalog_hash(jsonb_build_object('source_type',p_source_type,'source_id',p_source_id,'currency',p_currency,'effective_at',p_effective_at,'lines',p_lines));perform pg_advisory_xact_lock(hashtextextended('finance-post:'||p_source_posting_key,0));
 select * into saved from finance_private.ledger_transactions where source_posting_key=p_source_posting_key;if saved.id is not null then if saved.request_hash<>digest then raise exception 'IDEMPOTENCY_CONFLICT';end if;return saved.id;end if;
 for line in select value from jsonb_array_elements(p_lines) loop
  if jsonb_typeof(line)<>'object' or(line-array['account_code','learner_id','package_purchase_id','lot_id','signed_minor'])<>'{}' then raise exception 'VALIDATION_ERROR';end if;n:=app_private.package_safe_integer(line->'signed_minor',-9007199254740991);total:=total+n;
 end loop;if total<>0 then raise exception 'UNBALANCED_JOURNAL';end if;
 insert into finance_private.ledger_transactions(id,source_posting_key,source_type,source_id,request_hash,actor_account_id,command_id,currency,effective_at) values(id,p_source_posting_key,p_source_type,p_source_id,digest,(p_context->>'actor_account_id')::uuid,(p_context->>'command_id')::uuid,p_currency,p_effective_at);
 for line in select value from jsonb_array_elements(p_lines) loop insert into finance_private.ledger_lines(transaction_id,account_code,learner_id,package_purchase_id,lot_id,signed_minor,currency) values(id,line->>'account_code',(line->>'learner_id')::uuid,(line->>'package_purchase_id')::uuid,(line->>'lot_id')::uuid,(line->>'signed_minor')::bigint,p_currency);end loop;return id;
end $$;
create function finance_private.finance_issue_charge(p_charge_type text,p_learner_id uuid,p_responsible_account_id uuid,p_package_purchase_id uuid,p_enrollment_id uuid,p_contract_version_id uuid,p_accepted_terms_hash text,p_amount_minor bigint,p_context jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare id uuid:=gen_random_uuid();lines jsonb:='[]';begin
 insert into finance_private.charges(id,charge_type,learner_id,responsible_account_id,package_purchase_id,enrollment_id,accepted_contract_version_id,accepted_terms_hash,amount_minor,currency) values(id,p_charge_type,p_learner_id,p_responsible_account_id,p_package_purchase_id,p_enrollment_id,p_contract_version_id,p_accepted_terms_hash,p_amount_minor,'EGP');
 if p_amount_minor<>0 then lines:=jsonb_build_array(jsonb_build_object('account_code','receivable','learner_id',p_learner_id,'package_purchase_id',p_package_purchase_id,'signed_minor',p_amount_minor),jsonb_build_object('account_code','deferred_package_obligation','learner_id',p_learner_id,'package_purchase_id',p_package_purchase_id,'signed_minor',-p_amount_minor));end if;
 perform finance_private.finance_post_balanced('charge:'||id,'charge_issued',id,'EGP',now(),lines,p_context);return id;
end $$;

create function app_private.package_command(p_name text,p_input jsonb,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare actor uuid;context jsonb;purchase app_private.package_purchases%rowtype;policy app_private.package_grant_policy_versions%rowtype;contract jsonb;view jsonb;resource uuid:=gen_random_uuid();version integer:=1;result jsonb:='{}';lot_id uuid;movement_id uuid;charge_id uuid;quanta bigint;amount bigint;expiry timestamptz;lines jsonb;target uuid;begin
 actor:=app_private.require_actor();
 if p_name in('create_package_grant_policy','approve_package_grant_policy','approve_package_grant') then perform app_private.require_role(actor,'admin');
 elsif p_name='purchase_package' then perform app_private.package_assert_scope(actor,(p_input->>'learner_id')::uuid,'payments');
 else raise exception 'VALIDATION_ERROR';end if;
 context:=app_private.package_begin(actor,p_name,p_input,p_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 if p_name='purchase_package' then
  view:=app_private.package_contract_dto((p_input->>'package_contract_version_id')::uuid);contract:=view->'contract';
  if p_input->>'accepted_terms_hash' is distinct from view->>'terms_hash' then raise exception 'VERSION_CONFLICT';end if;
  perform app_private.package_lock_learner((p_input->>'learner_id')::uuid);
  insert into app_private.package_purchases(id,learner_id,purchaser_account_id,contract_version_id,contract_snapshot,contract_hash,accepted_by,planned_credit_quanta,purchase_value_minor,currency,purchase_activation_rule) values(resource,(p_input->>'learner_id')::uuid,actor,(p_input->>'package_contract_version_id')::uuid,contract,view->>'terms_hash',actor,(contract->>'grant_credit_quanta')::bigint,(contract->>'purchase_value_minor')::bigint,'EGP','full_settled_charge') returning * into purchase;
  charge_id:=finance_private.finance_issue_charge('package_purchase',purchase.learner_id,actor,purchase.id,null,purchase.contract_version_id,purchase.contract_hash,purchase.purchase_value_minor,context);
  update app_private.package_purchases set charge_id=package_command.charge_id where id=purchase.id;
  insert into app_private.package_purchase_acceptances(purchase_id,learner_id,actor_account_id,contract_hash) values(purchase.id,purchase.learner_id,actor,purchase.contract_hash);
  result:=jsonb_build_object('package_purchase_id',purchase.id,'charge_id',charge_id);perform set_config('response.status','201',true);
 elsif p_name='create_package_grant_policy' then
  if cardinality(app_private.package_grant_policy_errors(p_input->'content'))>0 then raise exception 'VALIDATION_ERROR';end if;
  insert into app_private.package_grant_policy_versions(id,content,environment_scope,is_synthetic,created_by) values(resource,p_input->'content',case when app_private.catalog_environment() in('test','development') then 'development_test' else 'production' end,app_private.catalog_environment() in('test','development'),actor);
  result:=jsonb_build_object('grant_policy_version_id',resource,'validation_errors','[]'::jsonb);perform set_config('response.status','201',true);
 elsif p_name='approve_package_grant_policy' then
  select * into policy from app_private.package_grant_policy_versions where id=(p_input->>'grant_policy_version_id')::uuid for update;
  if policy.id is null then raise exception 'NOT_FOUND';end if;if policy.version is distinct from(p_input->>'expected_version')::int then raise exception 'VERSION_CONFLICT';end if;if policy.status<>'draft' then raise exception 'STATE_CONFLICT';end if;
  if length(btrim(coalesce(p_input->>'approval_note',''))) not between 1 and 2000 or p_input->>'effective_at' is null or not isfinite((p_input->>'effective_at')::timestamptz) then raise exception 'VALIDATION_ERROR';end if;
  perform app_private.assert_catalog_publication(app_private.catalog_environment(),policy.environment_scope,policy.is_synthetic);
  for target in select value::uuid from jsonb_array_elements_text(policy.content->'eligible_package_contract_version_ids') loop perform app_private.package_contract_snapshot(target);end loop;
  update app_private.package_grant_policy_versions set status='approved',approved_by=actor,approved_at=now(),effective_at=(p_input->>'effective_at')::timestamptz,approval_note=p_input->>'approval_note',version=policy.version+1,updated_at=now() where id=policy.id returning package_grant_policy_versions.version into version;
  resource:=policy.id;result:=jsonb_build_object('state','approved');
 elsif p_name='approve_package_grant' then
  purchase:=app_private.package_lock_purchase((p_input->>'package_id')::uuid);resource:=purchase.id;
  if purchase.version is distinct from(p_input->>'expected_version')::int then raise exception 'VERSION_CONFLICT';end if;
  if purchase.purchase_state='cancelled' then raise exception 'STATE_CONFLICT';end if;
  quanta:=app_private.package_safe_integer(p_input->'credit_quanta',1);amount:=app_private.package_safe_integer(p_input->'carrying_value_minor');
  if p_input->>'currency' is distinct from 'EGP' or p_input->>'grant_kind' is null or p_input->>'grant_kind' not in('complimentary','approved_credit') or length(btrim(coalesce(p_input->>'reason',''))) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
  if p_input->>'grant_kind'='approved_credit' then if p_input->>'source_credit_id' is null then raise exception 'VALIDATION_ERROR';end if;raise exception 'DEPENDENCY_UNAVAILABLE';end if;
  if p_input->>'source_credit_id' is not null then raise exception 'VALIDATION_ERROR';end if;
  if p_input->>'grant_policy_version_id' is null then
   select * into policy from app_private.package_grant_policy_versions where status='approved' and effective_at<=now() and content->>'valuation_rule'='zero_value' and content->'eligible_package_contract_version_ids'?purchase.contract_version_id::text;
   if not found or(select count(*) from app_private.package_grant_policy_versions where status='approved' and effective_at<=now() and content->>'valuation_rule'='zero_value' and content->'eligible_package_contract_version_ids'?purchase.contract_version_id::text)<>1 then raise exception 'POLICY_INCOMPLETE';end if;
  else select * into policy from app_private.package_grant_policy_versions where id=(p_input->>'grant_policy_version_id')::uuid for share;end if;
  if policy.id is null or policy.status<>'approved' or policy.effective_at>now() or not(policy.content->'eligible_package_contract_version_ids'?purchase.contract_version_id::text) or quanta>(policy.content->>'maximum_credit_quanta_per_grant')::numeric or amount>(policy.content->>'maximum_carrying_value_minor_per_grant')::numeric or(amount>0 and(policy.content->>'valuation_rule'<>'reviewed_exact_capped_subsidy' or p_input->>'grant_policy_version_id' is null)) then raise exception 'POLICY_INCOMPLETE';end if;
  perform app_private.assert_catalog_publication(app_private.catalog_environment(),policy.environment_scope,policy.is_synthetic);
  if p_input->>'evidence_file_id' is not null then raise exception 'EVIDENCE_REQUIRED';end if;
  if amount>0 and not(policy.is_synthetic and app_private.catalog_environment() in('test','development')) then raise exception 'EVIDENCE_REQUIRED';end if;
  contract:=purchase.contract_snapshot;expiry:=case when contract->>'expiry_mode'='days_from_grant' then now()+interval '1 second'*((contract->>'expiry_days')::numeric*86400)::double precision else null end;
  if expiry is not null then perform app_private.booking_validate_times(now(),expiry);end if;
  lot_id:=gen_random_uuid();insert into app_private.package_lots(id,purchase_id,learner_id,origin_kind,original_lot_id,grant_policy_version_id,contract_version_id,eligibility_snapshot,base_duration_minutes,coverage_rule,expires_at,grant_source_id,balances) values(lot_id,purchase.id,purchase.learner_id,'complimentary',lot_id,policy.id,purchase.contract_version_id,contract,(contract->>'base_duration_minutes')::int,contract->>'coverage_rule',expiry,(context->>'command_id')::uuid,app_private.package_empty_balance());
  movement_id:=app_private.package_append_movement(lot_id,'grant',jsonb_build_object('granted_credit_quanta',quanta,'available_credit_quanta',quanta,'granted_value_minor',amount,'available_value_minor',amount),jsonb_build_object('credit_quanta',quanta,'value_minor',amount,'to_bucket','available','customer_reason_code','complimentary_bonus'),context,'grant:'||lot_id);
  if amount>0 then lines:=jsonb_build_array(jsonb_build_object('account_code','promotional_subsidy_expense','learner_id',purchase.learner_id,'package_purchase_id',purchase.id,'lot_id',lot_id,'signed_minor',amount),jsonb_build_object('account_code','deferred_package_obligation','learner_id',purchase.learner_id,'package_purchase_id',purchase.id,'lot_id',lot_id,'signed_minor',-amount));perform finance_private.finance_post_balanced('bonus:'||lot_id,'complimentary_subsidy',lot_id,'EGP',now(),lines,context);end if;
  update app_private.package_purchases set version=purchase.version+1,updated_at=now() where id=purchase.id returning package_purchases.version into version;
  perform app_private.package_balance(purchase.id);
  result:=jsonb_build_object('lot_id',lot_id,'grant_movement_id',movement_id);perform set_config('response.status','201',true);
 end if;
 return app_private.package_finish(context,resource,version,result,p_name,jsonb_build_object('package_purchase_id',case when purchase.id is not null then purchase.id else null end,'resource_id',resource));
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'VALIDATION_ERROR';end $$;
create function api.purchase_package(p_learner_id uuid,p_package_contract_version_id uuid,p_accepted_terms_hash text,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.package_command('purchase_package',jsonb_build_object('learner_id',p_learner_id,'package_contract_version_id',p_package_contract_version_id,'accepted_terms_hash',p_accepted_terms_hash),p_idempotency_key) $$;
create function api.create_package_grant_policy(p_content jsonb,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.package_command('create_package_grant_policy',jsonb_build_object('content',p_content),p_idempotency_key) $$;
create function api.approve_package_grant_policy(p_grant_policy_version_id uuid,p_effective_at timestamptz,p_approval_note text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.package_command('approve_package_grant_policy',jsonb_build_object('grant_policy_version_id',p_grant_policy_version_id,'effective_at',p_effective_at,'approval_note',p_approval_note,'expected_version',p_expected_version),p_idempotency_key) $$;
create function api.approve_package_grant(p_package_id uuid,p_credit_quanta bigint,p_carrying_value_minor bigint,p_currency text,p_grant_kind text,p_grant_policy_version_id uuid,p_source_credit_id uuid,p_reason text,p_evidence_file_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select app_private.package_command('approve_package_grant',jsonb_build_object('package_id',p_package_id,'credit_quanta',p_credit_quanta,'carrying_value_minor',p_carrying_value_minor,'currency',p_currency,'grant_kind',p_grant_kind,'grant_policy_version_id',p_grant_policy_version_id,'source_credit_id',p_source_credit_id,'reason',p_reason,'evidence_file_id',p_evidence_file_id,'expected_version',p_expected_version),p_idempotency_key) $$;
create function api.get_package_contract(p_package_contract_version_id uuid,p_learner_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();begin perform app_private.package_assert_scope(actor,p_learner_id,'payments',true);return app_private.package_contract_dto(p_package_contract_version_id);end $$;
create function api.get_my_package(p_package_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();p app_private.package_purchases%rowtype;begin select * into p from app_private.package_purchases where id=p_package_id;if p.id is null then raise exception 'NOT_FOUND';end if;perform app_private.package_assert_scope(actor,p.learner_id,'payments',true);
 return jsonb_build_object('package',app_private.package_summary(p.id,actor),'contract',p.contract_snapshot,'purchase_terms_hash',p.contract_hash,'eligible_offers',app_private.package_offer_labels(p.contract_snapshot),'lot_page',jsonb_build_object('items','[]'::jsonb,'next_cursor',null),'movement_page',jsonb_build_object('items','[]'::jsonb,'next_cursor',null),'coverage_page',jsonb_build_object('items','[]'::jsonb,'next_cursor',null),'lineage_page',jsonb_build_object('items','[]'::jsonb,'next_cursor',null));end $$;

create function app_private.package_preserve_history() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'IMMUTABLE_RECORD';end if;
 if tg_table_name='package_lots' then if(to_jsonb(old)-array['balances','version']) is distinct from(to_jsonb(new)-array['balances','version']) then raise exception 'IMMUTABLE_RECORD';end if;
 elsif tg_table_name='package_purchases' then if(to_jsonb(old)-array['charge_id','purchase_state','activated_at','version','updated_at']) is distinct from(to_jsonb(new)-array['charge_id','purchase_state','activated_at','version','updated_at']) or(old.charge_id is not null and new.charge_id is distinct from old.charge_id) then raise exception 'IMMUTABLE_RECORD';end if;
 elsif tg_table_name='package_grant_policy_versions' then if old.status<>'draft' then raise exception 'IMMUTABLE_RECORD';end if;
 else raise exception 'IMMUTABLE_RECORD';end if;return new;
end $$;
do $$ declare item record;begin
 for item in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where(n.nspname='app_private' and c.relname in('learner_financial_mutex','package_grant_policy_versions','package_purchases','package_purchase_acceptances','package_lots','package_reservations','package_reservation_allocations','package_transfers','entitlement_movements','remedy_reservations','package_due_runs')) or(n.nspname='finance_private' and c.relname in('charges','ledger_transactions','ledger_lines','remedy_sources')) loop
  execute format('alter table %I.%I enable row level security',item.nspname,item.relname);
  execute format('grant select,insert on %I.%I to git_tutor_commands',item.nspname,item.relname);
  execute format('create policy package_commands on %I.%I to git_tutor_commands using(true) with check(true)',item.nspname,item.relname);
  execute format('revoke all on %I.%I from anon,authenticated,service_role,git_tutor_worker',item.nspname,item.relname);
 end loop;
end $$;
grant update on app_private.package_grant_policy_versions,app_private.package_purchases,app_private.package_lots,app_private.package_reservations,app_private.remedy_reservations,finance_private.remedy_sources to git_tutor_commands;
do $$ declare target text;begin
 foreach target in array array['app_private.package_lots','app_private.package_purchases','app_private.package_grant_policy_versions'] loop execute format('create trigger preserve_package_history before update or delete on %s for each row execute function app_private.package_preserve_history()',target);end loop;
 foreach target in array array['app_private.package_purchase_acceptances','app_private.package_reservation_allocations','app_private.package_transfers','app_private.entitlement_movements','app_private.package_due_runs','finance_private.charges','finance_private.ledger_transactions','finance_private.ledger_lines'] loop execute format('create trigger immutable_package_source before update or delete on %s for each row execute function app_private.reject_immutable_change()',target);end loop;
end $$;
do $$ declare f record;begin
 for f in select p.oid::regprocedure::text as signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname like 'package_%') or(n.nspname='finance_private' and p.proname like 'finance_%') or(n.nspname='api' and p.proname in('purchase_package','create_package_grant_policy','approve_package_grant_policy','approve_package_grant','get_package_contract','get_my_package')) loop
  execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;end $$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
notify pgrst,'reload schema';
